#include <spacerad/DeviceResponse.h>
#include <QCoreApplication>
#include <QFile>
#include <QTemporaryDir>
#include <functional>
#include <iostream>
#include <stdexcept>
using namespace spacerad;
namespace { int checks=0; void check(bool ok,const char* n){++checks;if(!ok)throw std::runtime_error(n);std::cout<<"PASS "<<n<<'\n';} bool rejects(std::function<void()> f){try{f();return false;}catch(...){return true;}} void write(const QString& p,const QByteArray& b){QFile f(p);if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate)||f.write(b)!=b.size())throw std::runtime_error("write");} }
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{QTemporaryDir temp;auto root=temp.path();auto p=Project::demo();p.volumes={{"Shell","G4_Al",{0,0,0},{30,30,30},.5,false},{"OBC_Si","G4_Si",{0,0,0},{20,20,20},0,true}};p.spectra.clear();Spectrum s;s.particle="proton";s.energy={1,2,3};s.values={2,3,2};s.prepare();p.spectra.push_back(s);p.duration=10;p.validate();QByteArray csv="device_id,metric,particle,energy_MeV,response,response_unit,angular_basis,reference\nOBC_Si,ddd,proton,1,1,MeV_cm2_per_g,isotropic_omnidirectional,NIEL ref\nOBC_Si,ddd,proton,2,2,MeV_cm2_per_g,isotropic_omnidirectional,NIEL ref\nOBC_Si,ddd,proton,3,1,MeV_cm2_per_g,isotropic_omnidirectional,NIEL ref\n";write(root+"/response.csv",csv);auto table=loadDeviceResponseCsv(root+"/response.csv");check(table.metric=="ddd"&&table.curves.size()==1,"DDD response CSV parses");auto bomCsv=csv; bomCsv.prepend("\xEF\xBB\xBF"); write(root+"/bom.csv",bomCsv);check(loadDeviceResponseCsv(root+"/bom.csv").curves.size()==1,"Excel UTF-8 BOM response CSV parses");auto fold=foldDeviceResponseTable(p,table);check(fold.at("rows").size()==1&&fold.at("rows")[0].at("niel_dose_Gy").get<double>()>0,"DDD fold produces NIEL dose");auto fluence=p.convertedQuantity(engine::SpectrumQuantity::Fluence);auto fluenceFold=foldDeviceResponseTable(fluence,table);check(std::abs(fold.at("rows")[0].at("folded_value").get<double>()-fluenceFold.at("rows")[0].at("folded_value").get<double>())<1e-10,"Flux and converted fluence folds agree without double exposure scaling");QByteArray see="device_id,metric,particle,energy_MeV,response,response_unit,angular_basis,reference\nOBC_Si,see,proton,1,1e-6,cm2_per_device,isotropic_omnidirectional,SEE ref\nOBC_Si,see,proton,2,2e-6,cm2_per_device,isotropic_omnidirectional,SEE ref\nOBC_Si,see,proton,3,1e-6,cm2_per_device,isotropic_omnidirectional,SEE ref\n";write(root+"/see.csv",see);auto seeFold=foldDeviceResponseTable(p,loadDeviceResponseCsv(root+"/see.csv"));check(seeFold.at("rows")[0].contains("poisson_probability_at_least_one"),"SEE fold exposes Poisson assumption");check(deviceResponseCsv(seeFold).contains("expected_events_per_device"),"SEE export declares result unit");QByteArray badAngular="device_id,metric,particle,energy_MeV,response,response_unit,angular_basis,reference\nOBC_Si,ddd,proton,1,1,MeV_cm2_per_g,beam,ref\nOBC_Si,ddd,proton,2,1,MeV_cm2_per_g,beam,ref\nOBC_Si,ddd,proton,3,1,MeV_cm2_per_g,beam,ref\n";write(root+"/angular.csv",badAngular);check(rejects([&]{loadDeviceResponseCsv(root+"/angular.csv");}),"Incompatible angular response rejected before folding");QByteArray bad="device_id,metric,particle,energy_MeV,response,response_unit,angular_basis,reference\nOBC_Si,ddd,proton,2,1,MeV_cm2_per_g,isotropic_omnidirectional,ref\nOBC_Si,ddd,proton,3,1,MeV_cm2_per_g,isotropic_omnidirectional,ref\n";write(root+"/bad.csv",bad);check(rejects([&]{foldDeviceResponseTable(p,loadDeviceResponseCsv(root+"/bad.csv"));}),"Response range gaps rejected");QByteArray wrong="device_id,metric,particle,energy_MeV,response,response_unit,angular_basis,reference\nUnknown,ddd,proton,1,1,MeV_cm2_per_g,isotropic_omnidirectional,ref\nUnknown,ddd,proton,2,1,MeV_cm2_per_g,isotropic_omnidirectional,ref\nUnknown,ddd,proton,3,1,MeV_cm2_per_g,isotropic_omnidirectional,ref\n";write(root+"/wrong.csv",wrong);check(rejects([&]{foldDeviceResponseTable(p,loadDeviceResponseCsv(root+"/wrong.csv"));}),"Unknown device rejected");auto badAngularTable=loadDeviceResponseCsv(root+"/response.csv");badAngularTable.angularBasis="beam";check(rejects([&]{foldDeviceResponseTable(p,badAngularTable);}),"Mismatched angular basis is rejected before folding");auto overflow=table;overflow.curves[0].values={1e308,1e308,1e308};check(rejects([&]{foldDeviceResponseTable(p,overflow);}),"Nonfinite response fold is rejected");auto wrongMetric=table;wrongMetric.responseUnit="cm2_per_device";check(rejects([&]{foldDeviceResponseTable(p,wrongMetric);}),"Metric response unit is enforced");auto report=saveDeviceResponseStudy(p,root+"/response.csv",root+"/study");check(loadDeviceResponseStudy(root+"/study")==report,"Study archive reconstructs exactly");QFile saved(root+"/study/response.csv");saved.open(QIODevice::ReadOnly);auto raw=saved.readAll();write(root+"/study/response.csv",raw+"\n");check(rejects([&]{loadDeviceResponseStudy(root+"/study");}),"Study tamper rejected");std::cout<<checks<<" device response contract checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
